            else: cur=[v]
            prev=v
        if len(cur)>=3: rs.append(tuple(cur))
        if rs: seqs.append((i,rs))
    # strays: nonzero cells not in any anchor run of their own row
    def seq_of(i,j,v):
        cand=[]
        for si,runs in seqs:
            if i==si and v in runs:
                idx=runs.index(v)
                d=abs(j-runs[0])
