                pass
        # recompute: cell is stray if it's not part of a >=3 run
        inrun=[False]*W
        for si,runs in seqs:
            if si==i:
                for k,(a,b) in enumerate(zip(runs,r)):
                    pass
        # simpler: mark cells belonging to a run of len>=3
        belong=set()
        for si,runs in seqs:
