            # assign: if cell is part of a group run, keep; else stray -> assign to group containing its color
            if (r,c) in {(a,b) for a,_,s in groups for b in range(len(s))}: continue
            assigns=[g for g in groups if v in g[2]]
            if not assigns: continue
            grp=assigns[0]; s=grp[2]; k=s.index(v)
