import json
def f(gi):
    h=len(gi); w=len(gi[0]); out=[row[:] for row in gi]
    # find runs (contiguous nonzero)
    runs=[]
    for r in range(h):
        c=0
        while c<w:
            if gi[r][c]!=0:
                j=c
                while j<w and gi[r][j]!=0: j+=1
                runs.append((r,c,j,gi[r][c:j]))
                c=j
            else: c+=1
    occ={}
    for r,c,j,s in runs:
        for b in range(len(s)): occ.setdefault(s[b],[]).append((r,c+len(s)-1-b,b,s))
    for r in range(h):
        for c in range(w):
            v=gi[r][c]
            if v==0 or gi[r][c] in [s for _,_,_,s in runs for b in range(len(s)) if _==r and b==c]: continue
            cands=occ.get(v,[])
            if not cands: continue
            best=min(cands, key=lambda t: abs(r-t[0])+abs(c-t[1]))
            _,oc_c,_,s=best
            shift=c-oc_c
            for j in range(len(s)):
                cc=shift+j
                if 0<=cc<w and out[r][cc]==0: out[r][cc]=s[j]
    return out
