def f(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    # background = most common
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    # runs: maximal uniform horizontal segments len>=2
    runs=[]
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]!=bg:
                c0=c
                v=g[r][c]
                while c<W and g[r][c]==v: c+=1
                if c-c0>=2: runs.append((r,c0,c-1,v))
            else: c+=1
    # marker cells: non-bg cells not in any run
    inrun=set()
    for r0,c0,c1,v in runs:
        for cc in range(c0,c1+1): inrun.add((r0,cc))
    marks=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg and (r,c) not in inrun]
    seqs=runs  # each run = sequence
    res=[r[:] for r in g]
    # marker rays: full column through, marker->4
    for r,c,v in marks:
        res[r][c]=4
        for rr in range(H): res[rr][c]=v
    # structure rays: perpendicular full extent
    for r0,c0,c1,v in runs:
        for cc in range(c0,c1+1):
            for rr in range(H): res[rr][cc]=v
    return res
