def solve(gi):
    h=len(gi); w=len(gi[0])
    go=[row[:] for row in gi]
    # seq rows: contain a horizontal run of >=2 equal nonzero values... actually runs of distinct seq colors. Find bottom-like rows: rows where nonzero forms contiguous block(s)
    seq_rows=[]
    for r in range(h):
        row=gi[r]
        blocks=[]
        c=0
        while c<w:
            if row[c]!=0:
                s=row[c]; k=c
                while k<w and row[k]==s: k+=1
                if k-c>=2: blocks.append((s,k-c,c))
                c=k
            else: c+=1
        if blocks: seq_rows.append(r)
    non_seq_rows={r for r in range(h) if r not in seq_rows}
    seqs={}
    for r in seq_rows:
        row=gi[r]
        for c,v in enumerate(row):
            if v!=0 and (c==0 or row[c-1]==0 or True):
                pass
        # collect runs of len>=2
        runs=[]; c=0
        while c<w:
            if row[c]!=0:
                s=row[c]; k=c
                while k<w and row[k]==s: k+=1
                if k-c>=2: runs.append((s,k-c,c))
                c=k
            else: c+=1
        seqs.setdefault(r,runs)
    for r in sorted(non_seq_rows):
        row=gi[r]
        # process anchors: nonzero cells; but skip cells adjacent-part of a multi-cell run (none here since non-seq rows are singletons)
        for c,v in enumerate(row):
            if v==0: continue
            if r in seqs and any(run[0]==v for run in seqs[r]): 
                continue  # this row is actually a seq row misdetected? fine
            hits=[si for si,runs in seqs.items() if any(run[0]==v for run in runs)]
            if not hits: continue
            si=hits[0]; runs=seqs[si]
            pos=None
            for run in runs:
                if run[0]==v: pos=run[1]-1
            if pos is None: continue
            L=pos   # cells to left of anchor along seq
            R=len(runs[0])-1-pos
            for k in range(1,L+1):
                go[r][c-k]=runs[0][pos-k] if pos-k>=0 else runs[0][-((pos-k)%len(runs[0]))]
            for k in range(1,R+1):
                go[r][c+k]=runs[0][(pos+k)%len(runs[0])]
    return go
